INSERT INTO questionnaires (slug, name, definition) VALUES ('sf2a-vignettes', 'Two ways of noticing', '{"slug": "sf2a-vignettes", "name": "Two ways of noticing", "questionnaire_type": "composable", "instructions": "People notice things in different ways. Our brains can toggle between two modes: a doing mode, which is goal-directed and uses knowledge we already have, and a sensing mode, which explores our sensory world to discover new things.\n\nIn the doing mode, we look or listen to find something, like our keys, or to check that all is well, like a body ache or a strange sound outside. In the sensing mode, we look, listen, smell, taste or feel just out of curiosity, taking in whatever is there. Everyone does both at times, and neither is better. There are no right or wrong answers.", "pages": [{"id": "vig_p1", "components": [{"id": "vig_stem_1", "type": "information", "title": "How much is this person in the doing or sensing mode?", "body": "Rate each one from 1 Doing mode to 6 Sensing mode.", "image_url": "", "image_alt": ""}, {"id": "vig_1", "type": "likert", "question": "Priya walks along the shelves in the drug store, reading labels until finding the brand on her list.", "scale": [{"value": 1, "label": "1 Doing mode"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6 Sensing mode"}], "required": true, "allow_pna": true}, {"id": "vig_2", "type": "likert", "question": "Walking home late, Riley keeps listening for footsteps and watching the shadows on the empty street.", "scale": [{"value": 1, "label": "1 Doing mode"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6 Sensing mode"}], "required": true, "allow_pna": true}, {"id": "vig_3", "type": "likert", "question": "Waiting for a bus, Sam watches the light move on the wet road and listens to the cars go by.", "scale": [{"value": 1, "label": "1 Doing mode"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6 Sensing mode"}], "required": true, "allow_pna": true}]}, {"id": "vig_p2", "components": [{"id": "vig_stem_2", "type": "information", "title": "How much is this person in the doing or sensing mode?", "body": "Rate each one from 1 Doing mode to 6 Sensing mode.", "image_url": "", "image_alt": ""}, {"id": "vig_4", "type": "likert", "question": "Lee is photographing the light on a building, then stops trying for the perfect shot and just takes in the view.", "scale": [{"value": 1, "label": "1 Doing mode"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6 Sensing mode"}], "required": true, "allow_pna": true}, {"id": "vig_5", "type": "likert", "question": "In line at the ATM, Alex barely sees the street, busy working out a budget for next summer’s holiday.", "scale": [{"value": 1, "label": "1 Doing mode"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6 Sensing mode"}], "required": true, "allow_pna": true}, {"id": "vig_6", "type": "likert", "question": "Walking down the hallway, Maya notices how each breath feels, then the warmth spreading through both hands.", "scale": [{"value": 1, "label": "1 Doing mode"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6 Sensing mode"}], "required": true, "allow_pna": true}]}, {"id": "vig_p3", "components": [{"id": "vig_stem_3", "type": "information", "title": "How much is this person in the doing or sensing mode?", "body": "Rate each one from 1 Doing mode to 6 Sensing mode.", "image_url": "", "image_alt": ""}, {"id": "vig_7", "type": "likert", "question": "Jamie feels a racing heart and keeps checking it, to make sure nothing is wrong.", "scale": [{"value": 1, "label": "1 Doing mode"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6 Sensing mode"}], "required": true, "allow_pna": true}, {"id": "vig_8", "type": "likert", "question": "Drinking a morning coffee, Kai notices its bitterness and warmth, and that it tastes different from usual.", "scale": [{"value": 1, "label": "1 Doing mode"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6 Sensing mode"}], "required": true, "allow_pna": true}, {"id": "vig_9", "type": "likert", "question": "In a noisy room, Noor strains to catch a phone number in a voicemail.", "scale": [{"value": 1, "label": "1 Doing mode"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6 Sensing mode"}], "required": true, "allow_pna": true}]}, {"id": "vig_p4", "components": [{"id": "vig_self_head", "type": "information", "title": "Now, about you", "body": "", "image_url": "", "image_alt": ""}, {"id": "vig_self", "type": "likert", "question": "The last time you had a few minutes with nothing to do, how much were you in the doing or sensing mode?", "scale": [{"value": 1, "label": "1 Doing mode"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6 Sensing mode"}], "required": true, "allow_pna": true}]}], "interleave": {"items": ["vig_1", "vig_2", "vig_3", "vig_4", "vig_5", "vig_6", "vig_7", "vig_8", "vig_9"], "page_sizes": [3, 3, 3], "groups": [{"items": ["vig_3", "vig_4", "vig_6", "vig_8"], "min_gap": 1, "max_per_page": 2, "min_per_page": 1}, {"items": ["vig_1", "vig_2", "vig_5", "vig_7", "vig_9"], "min_gap": 1, "max_per_page": 2, "min_per_page": 1}]}, "vignettes": [{"id": "vig_1", "source": "V1", "kind": "Doing: finding something", "sensing": false}, {"id": "vig_2", "source": "V2", "kind": "Doing: keeping watch", "sensing": false}, {"id": "vig_3", "source": "V3", "kind": "Sensing: around me", "sensing": true}, {"id": "vig_4", "source": "V4", "kind": "Sensing: letting go of a goal", "sensing": true}, {"id": "vig_5", "source": "V5", "kind": "Doing: planning", "sensing": false}, {"id": "vig_6", "source": "V6", "kind": "Sensing: in the body", "sensing": true}, {"id": "vig_7", "source": "V7", "kind": "Doing: checking the body", "sensing": false}, {"id": "vig_8", "source": "V8", "kind": "Sensing: taste", "sensing": true}, {"id": "vig_9", "source": "V9", "kind": "Doing: finding something", "sensing": false}], "scoring": {"note": "Not a scale. Separation = mean(sensing vignettes) - mean(doing vignettes), 1 = Doing mode, 6 = Sensing mode. vig_self is the self-rating on the same anchors."}}'::jsonb)
INSERT INTO questionnaires (slug, name, definition) VALUES ('sf2a-scale', 'How you pay attention', '{"slug": "sf2a-scale", "name": "How you pay attention", "questionnaire_type": "composable", "instructions": "In general, how much do you agree with each statement? There are no right or wrong answers.", "pages": [{"id": "sf2a_p1", "components": [{"id": "sf2a_01", "type": "likert", "question": "Moving into the sensing mode comes easily to me", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf2a_33", "type": "likert", "question": "Only time spent getting things done feels worthwhile to me", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf2a_50", "type": "likert", "question": "When I notice something, I start explaining it to myself straight away", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf2a_21", "type": "likert", "question": "Noticing what I can see, hear or feel often shows me something about a situation I had not thought of", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf2a_47", "type": "likert", "question": "I don’t like going to events unless I know the full itinerary", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf2a_11", "type": "likert", "question": "For me, exploring what I see and hear is a different state of mind from planning and fixing", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf2a_30", "type": "likert", "question": "When I try to spend time in the sensing mode, I feel I should be doing something more useful", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf2a_17", "type": "likert", "question": "When I am stressed, a moment of looking around out of curiosity makes me less likely to react as usual", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}]}, {"id": "sf2a_p2", "components": [{"id": "sf2a_51", "type": "likert", "question": "When I notice something, I have trouble just letting it be", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf2a_23", "type": "likert", "question": "Even when I am busy, it feels worth pausing to notice the sights and sounds around me", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf2a_35", "type": "likert", "question": "In familiar places, I get curious about details I have not noticed before", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf2a_52", "type": "likert", "question": "When I notice a sensation, I take it in for a moment before deciding what to do about it", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf2a_28", "type": "likert", "question": "Looking closely at ordinary things around me often gives me a sense of wonder", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf2a_44", "type": "likert", "question": "When I eat something familiar, I notice whether I still like it as much as I expect", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf2a_26", "type": "likert", "question": "I value time spent just looking and listening, even when there is work to do", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf2a_09", "type": "likert", "question": "I often slip into the doing mode without meaning to", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}]}, {"id": "sf2a_p3", "components": [{"id": "sf2a_20", "type": "likert", "question": "When I feel unsafe, I lose my curiosity about what is around me", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf2a_10", "type": "likert", "question": "I can pay attention to what I’m feeling in my body in new or unfamiliar places", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf2a_attn_disagree", "type": "likert", "question": "To show that you are reading each statement, please select “Disagree” for this one.", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true}, {"id": "sf2a_31", "type": "likert", "question": "I enjoy taking a moment just to notice how my body feels, like my breathing, the soles of my feet, or posture", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf2a_34", "type": "likert", "question": "Even on rushed days, I find moments to notice the sky or the sounds around me", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf2a_08", "type": "likert", "question": "I can tell which moments in my day leave room for exploring what is around me", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf2a_22", "type": "likert", "question": "Seeing something from a new or unexpected perspective feels valuable to me in its own right", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf2a_03", "type": "likert", "question": "I question my ability to move into the sensing mode", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}]}, {"id": "sf2a_p4", "components": [{"id": "sf2a_45", "type": "likert", "question": "I can pause when something starts to bother me, before I do anything about it", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf2a_38", "type": "likert", "question": "When I am waiting somewhere, I look around out of curiosity instead of reaching for my phone", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf2a_32", "type": "likert", "question": "I enjoy noticing smells in ordinary places, like rain or coffee", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf2a_57", "type": "likert", "question": "When a sensation in my body is hard to name, I stay curious about it for a while", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf2a_24", "type": "likert", "question": "When stress narrows my focus, looking around out of curiosity matters even more to me", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf2a_58", "type": "likert", "question": "When I notice a sensation, my mind quickly moves on to thoughts about it", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf2a_07", "type": "likert", "question": "Even in dull places, like a waiting room, I can find something interesting to look at or listen to", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf2a_43", "type": "likert", "question": "During my day, I notice how my breathing or body feels, just out of curiosity", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}]}, {"id": "sf2a_p5", "components": [{"id": "sf2a_48", "type": "likert", "question": "I can let a sensation simply be, without figuring out what it means or where it leads", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf2a_14", "type": "likert", "question": "When I try to use the sensing mode, I notice how easily I shift back into thinking about what I have to do next", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf2a_25", "type": "likert", "question": "I enjoy exploring the sights, sounds and textures of ordinary moments", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf2a_attn_agree", "type": "likert", "question": "To show that you are reading each statement, please select “Agree” for this one.", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true}, {"id": "sf2a_56", "type": "likert", "question": "I react to things before I have really taken them in", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf2a_13", "type": "likert", "question": "The sensing and doing modes seem pretty similar to me", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "lab