Forage", "reverse_keyed": true}, {"id": "sf2a_43", "source": "F10", "factor": "Forage", "reverse_keyed": false}, {"id": "sf2a_44", "source": "F11", "factor": "Forage", "reverse_keyed": false}, {"id": "sf2a_45", "source": "sfc_32", "factor": "Letting be", "reverse_keyed": false}, {"id": "sf2a_46", "source": "sf6_40", "factor": "Letting be", "reverse_keyed": true}, {"id": "sf2a_47", "source": "sf6_47", "factor": "Letting be", "reverse_keyed": true}, {"id": "sf2a_48", "source": "sf6_21", "factor": "Letting be", "reverse_keyed": false, "study1_item": "sf6_21"}, {"id": "sf2a_49", "source": "sfc_10", "factor": "Letting be", "reverse_keyed": false}, {"id": "sf2a_50", "source": "sfc_12", "factor": "Letting be", "reverse_keyed": true}, {"id": "sf2a_51", "source": "sfc_14", "factor": "Letting be", "reverse_keyed": true}, {"id": "sf2a_52", "source": "sfc_26", "factor": "Letting be", "reverse_keyed": false}, {"id": "sf2a_53", "source": "sfc_28", "factor": "Letting be", "reverse_keyed": false}, {"id": "sf2a_54", "source": "sfc_29", "factor": "Letting be", "reverse_keyed": false}, {"id": "sf2a_55", "source": "sfc_30", "factor": "Letting be", "reverse_keyed": true}, {"id": "sf2a_56", "source": "sfc_31", "factor": "Letting be", "reverse_keyed": true}, {"id": "sf2a_57", "source": "L15", "factor": "Letting be", "reverse_keyed": false}, {"id": "sf2a_58", "source": "sfc_13", "factor": "Letting be", "reverse_keyed": true}], "attention_checks": {"sf2a_attn_disagree": 2, "sf2a_attn_agree": 5, "sf2a_attn_strongly_disagree": 1}, "factors": {"Access": {"definition": "Knowing that curious noticing is open to you, around you and in your body, and being able to turn to it.", "item_ids": ["sf2a_01", "sf2a_02", "sf2a_03", "sf2a_04", "sf2a_05", "sf2a_06", "sf2a_07", "sf2a_08", "sf2a_09", "sf2a_10"]}, "Understanding": {"definition": "Learning by sensing: what noticing shows you about yourself and a situation, including how stress pulls you into rushing and fixing.", "item_ids": ["sf2a_11", "sf2a_12", "sf2a_13", "sf2a_14", "sf2a_15", "sf2a_16", "sf2a_17", "sf2a_18", "sf2a_19", "sf2a_20", "sf2a_21"]}, "Valuing": {"definition": "Treating time spent noticing out of curiosity as worthwhile, and enjoying it.", "item_ids": ["sf2a_22", "sf2a_23", "sf2a_24", "sf2a_25", "sf2a_26", "sf2a_27", "sf2a_28", "sf2a_29", "sf2a_30", "sf2a_31", "sf2a_32", "sf2a_33"]}, "Forage": {"definition": "Habits of curious noticing in ordinary moments, around you and in your body. No amounts or frequencies.", "item_ids": ["sf2a_34", "sf2a_35", "sf2a_36", "sf2a_37", "sf2a_38", "sf2a_39", "sf2a_40", "sf2a_41", "sf2a_42", "sf2a_43", "sf2a_44"]}, "Letting be": {"definition": "Staying with what is noticed before explaining, resolving or acting on it. The pause can be brief: letting something be for a moment, then acting when you choose, still counts. Its opposite is the pull to add meaning, predict what comes next, or respond straight away.", "item_ids": ["sf2a_45", "sf2a_46", "sf2a_47", "sf2a_48", "sf2a_49", "sf2a_50", "sf2a_51", "sf2a_52", "sf2a_53", "sf2a_54", "sf2a_55", "sf2a_56", "sf2a_57", "sf2a_58"]}}}'::jsonb)
INSERT INTO questionnaires (slug, name, definition) VALUES ('sf2a-end', 'A few more statements', '{"slug": "sf2a-end", "name": "A few more statements", "questionnaire_type": "composable", "instructions": "A few more statements about how you pay attention. In general, how much do you agree with each statement? There are no right or wrong answers.", "pages": [{"id": "end_p1", "components": [{"id": "sf6_7", "type": "likert", "question": "Once I notice I have slipped into the doing mode without meaning to, I can shift back to sensing", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf6_8", "type": "likert", "question": "I can move into the sensing mode in new or unfamiliar places", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf6_12", "type": "likert", "question": "Returning to the sensing mode feels worth prioritizing, even when I am busy", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf6_18", "type": "likert", "question": "When stress narrows my focus, returning to the sensing mode matters even more to me", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf6_27", "type": "likert", "question": "I enjoy exploring the world through my senses", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf6_11", "type": "likert", "question": "I value time spent in the sensing mode, rather than always focusing on getting things done", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}]}], "source": "Study 1 wording (sf-pool6). With sf6_9, sf6_35, sf6_36 and sf6_44 in sf2a-scale (sf2a_01-03, sf2a_27), these complete the PSY240 trial primary score, Access + Valuing and savouring."}'::jsonb)
